 el('agentPhotoFile').onchange=async()=>{const file=el('agentPhotoFile').files[0];if(!file)return;const job=++photoJob;photoBusy=true;try{const data=await cropPhoto(file);if(data&&job===photoJob){draftPhoto=data;el('agentPhotoStatus').textContent='Foto pronta.';refreshPhoto();}}catch(e){el('agentPhotoStatus').textContent='Não foi possível abrir a foto. Tente JPEG ou PNG.';}finally{if(job===photoJob)photoBusy=false;el('agentPhotoFile').value='';}};


 const functionsList=['Supervisor','Coordenador','Motorista','Patrulheiro','Motociclista','Vídeo Monitoramento','Educação','Detran'];
