 function addFunction(value=''){const host=el('agentFunctions');if(host.children.length>=2)return;const row=document.createElement('div');row.className='space-y-2';const select=document.createElement('select');select.className='w-full rounded-xl bg-slate-800 border border-slate-600 p-3 text-white';select.setAttribute('aria-label','Função exercida');for(const v of ['',...functionsList,'__custom'])select.add(new Option(v==='__custom'?'Outra função':v||'Não informar',v));const custom=document.createElement('input');custom.className=select.className;custom.placeholder='Digite a função';custom.maxLength=100;custom.setAttribute('aria-label','Outra função');select.value=functionsList.includes(value)||!value?value:'__custom';custom.value=select.value==='__custom'?value:'';const sync=()=>{custom.hidden=select.value!=='__custom';custom.required=!custom.hidden;};select.onchange=sync;sync();row.append(select,custom);if(host.children.length){const remove=document.createElement('button');remove.type='button';remove.textContent='− Remover segunda função';remove.className='text-sm underline';remove.onclick=()=>{row.remove();el('addAgentFunction').hidden=false;syncTeam();};row.append(remove);}host.append(row);el('addAgentFunction').hidden=host.children.length>=2;}
 el('addAgentFunction').onclick=()=>addFunction();
 function normalizedChoices(p){const old=Array.isArray(p?.headerChoices)?p.headerChoices:[];const seen=new Set();const out=[];for(const item of old){if(item&&Object.hasOwn(headerLabels,item.key)&&!seen.has(item.key)){seen.add(item.key);out.push({key:item.key,on:!!item.on});}}for(const key of Object.keys(headerLabels))if(!seen.has(key))out.push({key,on:key==='matricula'||key==='scale'});return out;}
 function headerSlots(items, merge=true){const active=items.filter(x=>x.on).map(x=>x.key);if(merge&&active.includes('funcao')&&active.includes('team')){const first=Math.min(active.indexOf('funcao'),active.indexOf('team'));const rest=active.filter(k=>k!=='funcao'&&k!=='team');rest.splice(first,0,'funcao');return rest;}return active;}
 function drawChoices(){const host=el('headerChoices');host.replaceChildren();const slots=headerSlots(choices);const paired=choices.some(x=>x.key==='funcao'&&x.on)&&choices.some(x=>x.key==='team'&&x.on);for(const key of Object.keys(headerLabels)){const item=choices.find(x=>x.key===key);const row=document.createElement('div');row.className='flex items-center gap-2 py-2';const label=document.createElement('label');label.className='flex flex-1 items-center gap-2 text-sm';const check=document.createElement('input');check.type='checkbox';check.checked=item.on;check.dataset.headerKey=key;check.onchange=()=>{item.on=check.checked;if(item.on){choices=choices.filter(x=>x!==item);choices.push(item);}drawChoices();host.querySelector('[data-header-key="'+key+'"]').focus();};label.append(check,document.createTextNode(headerLabels[key]));row.append(label);const number=document.createElement('span');const rank=item.on?slots.indexOf(paired&&key==='team'?'funcao':key)+1:0;number.className='inline-flex items-center justify-center rounded-lg border border-slate-600 w-8 h-8 text-sm font-bold '+(rank?'text-amber-400':'text-slate-400');number.textContent=rank||'–';number.setAttribute('aria-label',rank?'Posição '+rank:'Não selecionado');row.append(number);host.append(row);}}
 el('resetHeaderOrder').onclick=()=>{choices=choices.map(x=>({...x,on:false}));drawChoices();};
 const headerFieldset=el('headerChoices').closest('fieldset'), headerHome=headerFieldset.parentNode, headerNext=headerFieldset.nextSibling;
