 const teamText=v=>!v?'':'Equipe '+normalizeTeam(v).replace(/^equipe\s+/i,'').toLocaleLowerCase('pt-BR').replace(/^./,x=>x.toUpperCase());
 const leadership=p=>Array.isArray(p.functions)&&p.functions.some(x=>typeof x==='string'&&/^(supervisor|coordenador)$/i.test(x.trim()));
 const headerFunction=p=>Array.isArray(p.functions)?p.functions.filter(x=>typeof x==='string'&&x.trim()).map(x=>{const v=x.trim();return /^(supervisor|coordenador)$/i.test(v)?v.toLocaleUpperCase('pt-BR'):functionsList.find(f=>f.toLocaleLowerCase('pt-BR')===v.toLocaleLowerCase('pt-BR'))||v;}).join(' / '):'';
 const headerTeam=(p,lead)=>p.team?(lead?'EQUIPE ':'Equipe ')+normalizeTeam(p.team).replace(/^equipe\s+/i,'').toLocaleUpperCase('pt-BR'):'';
