 async function saveImage(mode,photo){const p=currentProfile();if(!p)return;const next={...p,imageMode:mode,photo};try{amtStorage.setItem(PROFILE_KEY,JSON.stringify(next));await amtStorage.flush();applyProfile(next);if(!el('agentProfileScreen').classList.contains('hidden'))openAgentProfile();imageDialog.close();}catch(e){try{amtStorage.setItem(PROFILE_KEY,JSON.stringify(p));}catch(_){}alert('Não foi possível salvar a imagem.');}}
 function positionImageDialog(){if(!imageDialog.open)return;const r=el('agentHeaderImageButton').getBoundingClientRect(),w=imageDialog.offsetWidth,h=imageDialog.offsetHeight;imageDialog.style.left=Math.max(8,Math.min(r.left,window.innerWidth-w-8))+'px';imageDialog.style.top=Math.max(8,Math.min(r.top,window.innerHeight-h-8))+'px';}
 window.addEventListener('resize',positionImageDialog);imageDialog.addEventListener('click',e=>{if(e.target===imageDialog){const r=imageDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)imageDialog.close();}});
