    modal.innerHTML='<style id="amtMonthWheelStyles">#amtMonthWheelModal .amt-wheel-shell{width:min(100%,660px);border:1px solid rgba(255,255,255,.07);background:radial-gradient(ellipse at 50% 48%,#383838 0%,#292929 62%,#242424 100%);box-shadow:0 28px 90px rgba(0,0,0,.58),inset 0 1px 0 rgba(255,255,255,.04)}#amtMonthWheelModal .amt-wheel-stage{height:min(66vh,560px);min-height:330px;perspective:950px;transform-style:preserve-3d;background:radial-gradient(ellipse at center,rgba(255,255,255,.035),transparent 68%)}#amtMonthWheelModal .amt-wheel-list{height:100%;overflow-y:auto;text-align:center;scroll-snap-type:y mandatory;overscroll-behavior:contain;scrollbar-width:none;-webkit-overflow-scrolling:touch;transform-style:preserve-3d;padding-block:calc((min(66vh,560px) - 5.1rem)/2)}#amtMonthWheelModal .amt-wheel-list::-webkit-scrollbar{display:none}#amtMonthWheelModal .amt-wheel-item{display:block;width:100%;height:5.1rem;line-height:5.1rem;scroll-snap-align:center;text-align:center;text-transform:capitalize;white-space:nowrap;font-size:clamp(1.35rem,4.2vw,3rem);font-weight:400;color:rgba(255,255,255,.66);opacity:.62;filter:blur(1.15px);transform:perspective(700px) rotateX(24deg) scale(.82);transition:filter .12s linear,opacity .12s linear,transform .12s linear,color .12s linear;will-change:transform,filter}#amtMonthWheelModal .amt-wheel-item.is-selected{color:#fff;opacity:1;filter:blur(0);transform:perspective(700px) rotateX(0) scale(1.04);font-weight:500;text-shadow:0 1px 12px rgba(255,255,255,.08)}#amtMonthWheelModal .amt-wheel-highlight{position:absolute;z-index:2;inset-inline:2%;top:50%;height:5.1rem;transform:translateY(-50%);border-radius:999px;background:linear-gradient(90deg,rgba(255,255,255,.055),rgba(255,255,255,.105),rgba(255,255,255,.055));border-top:1px solid rgba(255,255,255,.07);border-bottom:1px solid rgba(0,0,0,.12);box-shadow:inset 0 1px 12px rgba(255,255,255,.025);pointer-events:none}#amtMonthWheelModal .amt-wheel-fade{position:absolute;z-index:3;inset-inline:0;height:24%;pointer-events:none}#amtMonthWheelModal .amt-wheel-fade-top{top:0;background:linear-gradient(to bottom,#292929 2%,rgba(41,41,41,.82) 38%,transparent 100%)}#amtMonthWheelModal .amt-wheel-fade-bottom{bottom:0;background:linear-gradient(to top,#292929 2%,rgba(41,41,41,.82) 38%,transparent 100%)}@media(max-width:480px){#amtMonthWheelModal .amt-wheel-stage{height:56vh;min-height:300px}#amtMonthWheelModal .amt-wheel-item{font-size:clamp(1.2rem,6vw,2rem)}#amtMonthWheelModal .amt-wheel-list{padding-block:calc((56vh - 5.1rem)/2)}}@media(prefers-reduced-motion:reduce){#amtMonthWheelModal .amt-wheel-item{transition:none}}</style><div class="amt-wheel-shell w-full rounded-[2rem] text-white p-4 sm:p-6 shadow-2xl space-y-4"><div class="grid grid-cols-2 gap-3 text-center text-xs sm:text-sm font-semibold tracking-[.22em] text-white/45"><span>MÊS</span><span>ANO</span></div><div class="amt-wheel-stage relative grid grid-cols-2 gap-2 sm:gap-5 overflow-hidden rounded-[1.5rem]"><div class="amt-wheel-highlight"></div><div id="amtMonthWheelMonths" class="amt-wheel-list relative z-[1]"></div><div id="amtMonthWheelYears" class="amt-wheel-list relative z-[1]"></div><div class="amt-wheel-fade amt-wheel-fade-top"></div><div class="amt-wheel-fade amt-wheel-fade-bottom"></div></div><div class="flex items-center justify-between gap-4 pt-1"><button type="button" id="amtMonthWheelBack" class="rounded-full border border-white/15 bg-white/10 px-7 py-3.5 text-lg font-semibold text-white shadow-inner active:scale-95 transition">Voltar</button><button type="button" id="amtMonthWheelUse" aria-label="Confirmar mês" title="Confirmar" class="flex h-[4.5rem] w-[4.5rem] items-center justify-center rounded-full bg-[#438ff0] text-4xl font-light text-white shadow-[0_8px_24px_rgba(67,143,240,.32)] active:scale-95 transition">✓</button></div></div>';
    document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeMonthWheel();});
    const monthList=modal.querySelector('#amtMonthWheelMonths'),yearList=modal.querySelector('#amtMonthWheelYears');let ticking=false;
    const updateFromScroll=()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{ticking=false;const nearest=(list)=>{const center=list.scrollTop+list.clientHeight/2;let best=0,dist=Infinity;[...list.children].forEach((el,i)=>{const d=Math.abs(el.offsetTop+el.offsetHeight/2-center);if(d<dist){dist=d;best=i;}});return best;};const mi=nearest(monthList),yi=nearest(yearList);monthWheelMonth=mi+1;monthWheelYear=Number(yearList.children[yi]?.dataset.year||monthWheelYear);monthWheelSetValue();[monthList,yearList].forEach((list)=>{const center=list.scrollTop+list.clientHeight/2;[...list.children].forEach(el=>{const distance=(el.offsetTop+el.offsetHeight/2-center)/el.offsetHeight;const abs=Math.abs(distance);const angle=Math.max(-68,Math.min(68,distance*23));const scale=Math.max(.68,1-abs*.115);const opacity=Math.max(.16,1-abs*.24);const blur=Math.min(3.2,abs*.72);el.classList.toggle('is-selected',abs<.48);el.style.opacity=String(opacity);el.style.filter='blur('+blur.toFixed(2)+'px)';el.style.transform='perspective(700px) rotateX('+angle.toFixed(1)+'deg) scale('+scale.toFixed(3)+')';});});});};
